import math

def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

solutions = []
for n in range(30, 201):
    divisors = get_divisors(n)

    # Check if n has at least 5 divisors
    if len(divisors) >= 5:
        # d1 = divisors[0] = 1
        # d2 = a (second smallest)
        # d3 = b (third smallest)
        # d5 = c (fifth smallest)

        a = divisors[1]
        b = divisors[2]
        c = divisors[4]

        # Check the relationship n = ab + ac + bc
        calculated_n = a * b + a * c + b * c

        if calculated_n == n:
            # We found a solution. We need to record n and its number of divisors.
            num_divisors = len(divisors)
            solutions.append({
                'n': n,
                'divisors': num_divisors,
                'a': a,
                'b': b,
                'c': c
            })

# Print the results in a structured way for recording
print("--- Solutions Found ---")
if solutions:
    for sol in solutions:
        print(f"n = {sol['n']}, Divisors = {sol['divisors']}, a={sol['a']}, b={sol['b']}, c={sol['c']}. Check: {sol['a']*sol['b'] + sol['a']*sol['c'] + sol['b']*sol['c']} == {sol['n']}")
else:
    print("No solutions found in the range 30 <= n <= 200.")

