def get_divisors(n):
    divs = []
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divs.append(i)
            if i*i != n:
                divs.append(n // i)
    return sorted(divs)

def verify_solution(n):
    divs = get_divisors(n)
    if len(divs) < 5:
        return False, "Fewer than 5 divisors"

    # a: second smallest (d2)
    a = divs[1]
    # b: third smallest (d3)
    b = divs[2]
    # c: fifth smallest (d5)
    c = divs[4]

    LHS = (a + b + c)**2
    RHS = a**2 + b**2 + c**2 + 2*n

    if LHS == RHS:
        # Equivalent to ab + ac + bc = n
        check_n = a*b + a*c + b*c
        if check_n == n:
            return True, f"Verified. n={n}, d(n)={len(divs)}. a={a}, b={b}, c={c}. Check: {check_n} = {n}"
        else:
            return False, f"Failed internal check. Expected n={check_n}, got n={n}"
    else:
        return False, f"Failed main equation check. LHS={LHS}, RHS={RHS}"

# Verification checks
print("--- Verification Checks ---")
print(verify_solution(36))
print(verify_solution(56))
print(verify_solution(135))

def get_divisors(n):
    divs = []
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divs.append(i)
            if i*i != n:
                divs.append(n // i)
    return sorted(divs)

def search_extended(start_n, end_n):
    solutions = []
    # We assume a=2, so n must be even and n > 2.
    for n in range(start_n, end_n + 1):
        if n % 2 != 0:
            continue

        divs = get_divisors(n)
        if len(divs) < 5:
            continue

        # Smallest divisor is 1. Second smallest is a=2 (since n is even).
        a = divs[1]
        if a != 2: # Should not happen if we check even numbers, but safe check
            continue

        # b: third smallest (d3)
        b = divs[2]
        # c: fifth smallest (d5)
        c = divs[4]

        # Check condition: n = ab + ac + bc
        check_n = a*b + a*c + b*c

        if check_n == n:
            solutions.append({
                'n': n,
                'd(n)': len(divs),
                'a': a,
                'b': b,
                'c': c,
                'check': f"{a}*{b} + {a}*{c} + {b}*{c} = {check_n}"
            })

    return solutions

print("--- Extended Numerical Search (200 < n < 500, assuming a=2) ---")
solutions = search_extended(201, 500)

if solutions:
    print(f"Found {len(solutions)} solutions:")
    for sol in solutions:
        print(f"N={sol['n']}, d(N)={sol['d(n)']}: a={sol['a']}, b={sol['b']}, c={sol['c']}. Check: {sol['check']}")
else:
    print("No solutions found in the range 201 <= n <= 499 assuming a=2.")

